package net.hivel.islandsrpg.gui;
import net.hivel.islandsrpg.IslandsRPGPlugin; import net.hivel.islandsrpg.quest.*; import net.hivel.islandsrpg.util.*; import org.bukkit.*; import org.bukkit.entity.Player; import org.bukkit.event.inventory.InventoryClickEvent; import org.bukkit.inventory.Inventory; import java.util.*;
public class QuestsGui { private final IslandsRPGPlugin p; private final Map<Integer,String> slots=new HashMap<>(); public QuestsGui(IslandsRPGPlugin p){this.p=p;} public void open(Player pl){Inventory inv=Bukkit.createInventory(null,54,ColorUtil.color("&8ǫᴜᴇꜱᴛꜱ")); slots.clear(); int slot=0; var d=p.data().get(pl); for(Quest q:p.quests().all()){int cur=d.activeQuests.getOrDefault(q.id(),new QuestProgress(q.id(),0)).current(); inv.setItem(slot,new ItemBuilder(Material.BOOK).name(q.displayName()).lore(List.of("&7ᴘʀᴏɢʀᴇꜱꜱ: &f"+cur+"/"+q.amount(),"","&7ʀᴇᴡᴀʀᴅꜱ:","&8▪ &f"+q.xp()+" xᴘ","&8▪ &f"+q.money()+" ᴍᴏɴᴇʏ","&8▪ &f"+q.fragments()+" ꜰʀᴀɢᴍᴇɴᴛꜱ","","&eᴄʟɪᴄᴋ ᴛᴏ ꜱᴛᴀʀᴛ")).build()); slots.put(slot++,q.id()); if(slot>=54)break;} pl.openInventory(inv);} public void click(InventoryClickEvent e){e.setCancelled(true); if(e.getWhoClicked() instanceof Player pl && slots.containsKey(e.getSlot())){p.quests().start(pl,slots.get(e.getSlot())); open(pl);}} }
